Section RgbsW.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O2Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Lemma rs_col : forall k regs M (j w ls ld comp dlo dhi : Z),
  (0 <= j < w)%Z -> Z.of_nat k = (w - j)%Z -> (w < 2 ^ 31)%Z -> (0 <= comp <= 2)%Z ->
  (0 <= ls)%Z -> (ls + w + 8 <= 2 ^ 64)%Z -> (0 <= ld)%Z -> (ld + 4 * w + 16 <= 2 ^ 64)%Z ->
  (0 <= dlo)%Z -> (dhi <= 2 ^ 64)%Z ->
  (forall q, (j <= q < w)%Z -> dlo <= xor3 (ld + comp + 4 * q) /\ xor3 (ld + comp + 4 * q) + 1 <= dhi)%Z ->
  (forall q, (j <= q < w)%Z -> ~ (dlo <= xor3 (ls + q) < dhi))%Z ->
  (forall q, (j <= q < w)%Z -> exists b : byte, M (Z_to_bv 64 (xor3 (ls + q))) = Some b) ->
  store_ok SEGS M (Z_to_bv 64 dlo) (Z.to_nat (dhi - dlo)) = true ->
  getr regs 15 = Z_to_bv 64 (ls + j) -> getr regs 14 = Z_to_bv 64 (ld + comp + 4 * j) -> getr regs 13 = Z_to_bv 64 (ls + w) ->
  exists regs' M',
    msteps SEGS (mkst regs (0x1b080 : word) M al_rom) (mkst regs' (0x1b05c : word) M' al_rom)
    /\ winside dlo dhi M M'
    /\ regs_agree (fun x => In x [13; 14; 15; 16; 17]%list) regs regs'.
