(* [comment removed for export] *)
Lemma rs_rows : forall k regs M (i h w comp datas wpls datad : Z),
  (0 <= i < h)%Z -> Z.of_nat k = (h - i)%Z -> (h < 2 ^ 31)%Z -> (1 <= w < 2 ^ 31)%Z -> (0 <= comp <= 2)%Z ->
  (datas mod 4 = 0)%Z -> (0 <= datas)%Z -> (0 <= wpls < 2 ^ 29)%Z -> (w <= 4 * wpls)%Z -> (datas + 4 * (wpls * h) + 16 <= 2 ^ 64)%Z ->
  (datad mod 4 = 0)%Z -> (0 <= datad)%Z -> (datad + 4 * (w * h) + 16 <= 2 ^ 64)%Z ->
  (datas + 4 * (wpls * h) <= datad \/ datad + 4 * (w * h) <= datas)%Z ->
  (forall a, (datas <= a < datas + 4 * (wpls * h))%Z -> exists b : byte, M (Z_to_bv 64 a) = Some b) ->
  store_ok SEGS M (Z_to_bv 64 datad) (Z.to_nat (4 * (w * h))) = true ->
  getr regs 11 = Z_to_bv 64 i -> getr regs 21 = Z_to_bv 64 w -> getr regs 22 = Z_to_bv 64 h ->
  getr regs 18 = Z_to_bv 64 (datas + 4 * wpls * i) -> getr regs 9 = Z_to_bv 64 (datad + comp + 4 * w * i) ->
  getr regs 8 = Z_to_bv 64 (4 * wpls) -> getr regs 10 = Z_to_bv 64 (4 * w) -> getr regs 12 = Z_to_bv 64 (datas + w) ->
  exists regs' M',
    msteps SEGS (mkst regs (0x1b06c : word) M al_rom) (mkst regs' (0x1b0a0 : word) M' al_rom)
    /\ winside datad (datad + 4 * (w * h)) M M'
    /\ regs_agree (fun x => In x [9; 11; 13; 14; 15; 16; 17; 18]%list) regs regs'.
Proof.
